"use strict";

const daemon = require("daemon");
const fs = require("fs");
const exec = require("child_process").exec;

// COMMON

const common = require("./apply_common");
const syslog = common.syslog();

const root_devs = [fs.realpathSync("/dev/disk/by-partlabel/rootfsA"),
    fs.realpathSync("/dev/disk/by-partlabel/rootfsB")];
function getOtherRootDevice() {
    let root_stat = fs.statSync("/");
    for (let idx=0; idx<root_devs.length; ++idx) {
        let dev = root_devs[idx];
        let dev_stat = fs.statSync(dev);
        if (root_stat.dev != dev_stat.rdev) {
            return dev;
        }
    }
}

function flashRW(boot_dev, callback) {
    syslog.debug("flashRW", boot_dev);
    const cmd = "echo 0 > /sys/block/" + boot_dev + "/force_ro";
    exec(cmd, function(error, stdout, stderr) {
        if (error) {
            common.fail(error);
        } else {
            callback();
        }
    });
}

function setRootDevice(device, callback) {
    syslog.debug("Set root device to", device);
    let idx = null;
    if (device == root_devs[0]) {
        idx = 1;
    } else if (device == root_devs[1]) {
        idx = 2;
    } else {
        // XXX fail
        syslog.error("Unknown root device", device);
        process.exit(1);
    }
    flashRW("mmcblk0boot1", function() {
        const cmd = "fw_setenv activeroot " + idx
            + " && fw_setenv upgrade_available 1"
            + " && fw_setenv bootcount 0"
            + " && fw_setenv bootlimit 1";
        exec(cmd, function(error, stdout, stderr) {
            if (error) {
                common.fail(error);
            } else {
                callback();
            }
        });
    });
}

function doOSInstall(to_version) {
    syslog.info("Begin OS update.");
    let extract_dir = common.extractDir(to_version, "os");
    let target_dev = getOtherRootDevice();
    let install_dir = "/tmp/other";
    common.makeScratchDir(install_dir, function() {
        common.mountFS(target_dev, install_dir, function() {
            common.applyUpdate(extract_dir, target_dev, install_dir, function() {
                common.unmountFS(target_dev, function() {
                    setRootDevice(target_dev, function() {
                        common.writeWorkState("verify", function() {
                            common.cleanScratchDir(extract_dir, function() {
                                syslog.info("Reboot and verify...");
                                common.reboot(function() { process.exit(0); });
                            });
                        });
                    });
                });
            });
        });
    });
}

function initOSUpdate(to_version, tarball) {
    syslog.info("Initialize os update");
    common.writeWorkState("init", function() {
        let extract_dir = common.extractDir(to_version, "os");
        common.unpackUpdate(extract_dir, tarball, function(extract_dir) {
            doOSInstall(to_version);
        });
    });
}

function retryOSUpdate(from_version, filter) {
    syslog.info("Retry os update from %s", from_version);
    common.waitForWifiLink(120, function(error) {
        if (error) {
            common.fail(error);
        } else {
            common.getAvailableUpdate("os", from_version, filter, 
                function(update, tarball) {
                    initOSUpdate(update.toVersion, tarball);
                });
        }
    });
}

function updateOtherRootfs(callback) {
    const other_dev = getOtherRootDevice();
    let this_dev = root_devs[0];
    if (this_dev == other_dev) {
        this_dev = root_devs[1];
    }
    syslog.debug("Copy", this_dev, "to", other_dev);
    exec("dd if=" + this_dev + " of=" + other_dev + " bs=16M", function(error, stdout, stderr) {
        if (error) {
            common.fail(error);
        } else {
            callback();
        }
    });
}

function checkBootCount(callback) {
    // If bootcount isn't 1, then we must have recovery-booted back to the
    // original partition. So, we should fail the update.
    syslog.debug("Check bootcount == 1");
    exec("fw_printenv bootcount", function(error, stdout, stderr) {
        if (error) {
            common.fail(error);
        } else {
            if (stdout == "bootcount=1\n") {
                callback();
            } else {
                common.fail(new Error("New OS didn't boot!"));
            }
        }
    });
}

function markSuccess(callback) {
    syslog.debug("OS booted successfully");
    flashRW("mmcblk0boot1", function() {
        exec("fw_setenv upgrade_available", function(error, stdout, stderr) {
            if (error) {
                common.fail(error);
            } else {
                callback();
            }
        });
    });
}

function doOSVerify(work_state) {
    // Not doing a real check here. Assume that the global final verify
    // check will catch really bad stuff, and that the fact that the
    // updater runs means the OS is good enough to update the other partition.
    checkBootCount(function() {
        markSuccess(function() {
            updateOtherRootfs(function() {
                common.finalizeInstall();
            });
        });
    });
}

function executeStep(step, work_state, gui) {
    const ws = work_state.current();
    const apply_time_est = common.bunzip2Estimate(ws.size);
    const verify_time_est = 30.0;
    const retry_time_est = 30.0 + (2.0 * apply_time_est);
    const times = common.timeToPct([apply_time_est, verify_time_est]);
    const apply_max_pct = times[0];
    const verify_max_pct = times[1];
    const retry_max_pct = apply_max_pct;
    const first_background = __dirname + "/Installer2.png";
    const second_background = __dirname + "/Installer2a.png";
    if (step == "verify") {
        gui.setBackground(second_background);
        gui.setPercent(apply_max_pct);
        gui.incrementTo(verify_max_pct, verify_time_est);
        doOSVerify(work_state);
    } else if (step == "retry") {
        gui.setBackground(second_background);
        gui.setPercent(0);
        gui.incrementTo(retry_max_pct, retry_time_est);
        retryOSUpdate(ws.from, ws.filter);
    } else {
        gui.setBackground(first_background);
        gui.setPercent(0);
        gui.incrementTo(apply_max_pct, apply_time_est);
        initOSUpdate(ws.to, ws.source);
    }
}

module.exports = {
    handlesSubsystem: function(subsystem) {
        return subsystem == "os";
    },
    execute: executeStep
}
